Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <regex>

std::string markdown_to_html(const std::string& markdown) {
    std::stringstream ss;
    std::string line;

    // Convert Markdown headings to HTML headings
    std::regex heading_regex("^#{1,6}(.+?)#*$");
    std::smatch heading_match;

    while (std::getline(std::stringstream(markdown), line)) {
        if (std::regex_match(line, heading_match, heading_regex)) {
            std::string level = std::string(heading_match.prefix().length(), '#');
            std::string content = heading_match.str(1);
            ss << "<h" << level.length() << ">" << content << "</h" << level.length() << ">\n";
        } else {
            ss << line << "\n";
        }
    }

    // Convert Markdown links to HTML links
    std::regex link_regex("\\[([^\\]]*)\\]\\(([^\\)]*)\\)");
    std::smatch link_match;

    std::string html = ss.str();
    std::regex_replace(html, std::regex("\\[([^\\]]*)\\]"), "$1");
    std::regex_replace(html, std::regex("\\(([^\\)]*)\\)"), "($1)");

    std::regex_search(html, link_match, link_regex);
    while (link_match.size() == 2) {
        std::string link_text = link_match.str(1);
        std::string link_url = link_match.str(2);
        html = std::regex_replace(html, std::regex("\\[" + link_text + "\\]", std::regex::format(("<a href=\"%1$s\">%1$s</a>", link_url))),
                                  std::regex::format("<a href=\"%1$s\">%2$s</a>", link_url, link_text));
        std::regex_search(html, link_match, link_regex);
    }

    return html;
}

int main() {
    std::string markdown = "## Heading\n\nText with [link](https://example.com) and **bold**";
    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

