    // Définir le mot à rechercher
    std::string search_word;

    // Demander à l'utilisateur d'entrer le mot à rechercher
    std::cout << "Entrez le mot à rechercher : ";
    std::cin >> search_word;

    // Ouvrir le fichier texte pour lecture
    std::ifstream file("filename.txt");

    if (!file.is_open()) {
        std::cerr << "Erreur : impossible d'ouvrir le fichier." << std::endl;
        return 1;
    }

    // Initialiser le compteur de mots trouvés
    int count = 0;

    // Lire chaque ligne du fichier
    std::string line;
    while (getline(file, line)) {
        // Convertir la ligne en minuscules pour ignorer la casse
        std::transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Utiliser la fonction find de la bibliothèque algorithm pour rechercher le mot
        size_t pos = line.find(search_word);
        while (pos != std::string::npos) {
            // Augmenter le compteur si le mot est trouvé
            count++;

            // Trouver la position du mot suivant dans la ligne
            pos = line.find(search_word, pos + 1);
        }
    }

    // Fermer le fichier
    file.close();

    // Afficher le nombre de mots trouvés
    std::cout << "Le mot '" << search_word << "' a été trouvé " << count << " fois dans le fichier." << std::endl;

    return 0;
